#pragma once

#include "endweave/protocol/version.h"

#include <algorithm>
#include <cstdint>
#include <optional>
#include <set>
#include <span>
#include <string_view>

namespace endweave {

/** The items, by name and sorted, that a hop's `From` has and its `To` has no mapping for. A hop
 * with any specialises it with `get()`, generated by tools/generate_items.py.
 * @see ViaBackwards ItemMappings. */
template <int From, int To>
struct ItemMappings {};

template <int From, int To>
concept HasItemMappings = requires { ItemMappings<From, To>::get(); };

/** Whether some hop from `From` to `To` maps an item. */
template <int From, int To>
consteval bool mapsItems()
{
    if constexpr (From == To) {
        return false;
    }
    else {
        return HasItemMappings<From, step(From, To)> || mapsItems<step(From, To), To>();
    }
}

/** The name `To` gives the item `From` calls `name`, one hop at a time, or none for an item `To`
 * lacks. An item no hop maps, such as an add-on's, keeps its name.
 * @see ViaVersion MappingData#getNewItemId. */
template <int From, int To>
std::optional<std::string_view> getNewItemName(std::string_view name)
{
    if constexpr (From == To) {
        return name;
    }
    else {
        constexpr int next = step(From, To);
        if constexpr (HasItemMappings<From, next>) {
            if (std::ranges::binary_search(ItemMappings<From, next>::get(), name)) {
                return std::nullopt;
            }
        }
        return getNewItemName<next, To>(name);
    }
}

/** The items of the server's ItemRegistryPacket that the client's version lacks, by the network id
 * the server gave them, which creative content and recipes name them by. */
class ItemRegistryStorage {
public:
    void setMissing(std::int32_t id)
    {
        missing_.insert(id);
    }

    [[nodiscard]] bool isMissing(std::int32_t id) const
    {
        return missing_.contains(id);
    }

private:
    std::set<std::int32_t> missing_;
};

} // namespace endweave
